    array("number" => 3, "name" => "Commander Red + Fortuneteller Baba + Tien Shinhan Saga", "rating" => 8.5, "episodes" => array(
        array("id" => "s3e1", "season" => 3, "number" => 1, "name" => "The Land of Korin", "airdate" => "15 Apr 1987", "runtime" => 30, "rating" => 7.8, "summary" => "The Red Ribbon Army tracks one of the Dragon Balls on a volcano island! However, a native is there to protect this sacred habitat and Goku is on his way as well!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436870.jpg"),
        array("id" => "s3e2", "season" => 3, "number" => 2, "name" => "The Nortorious Mercenary", "airdate" => "22 Apr 1987", "runtime" => 30, "rating" => 9, "summary" => "The Red Ribbon Army hires Mercenary Tao to eliminate Goku. The two meet on the island of Korin.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436869.jpg"),
        array("id" => "s3e3", "season" => 3, "number" => 3, "name" => "Tao Attacks!", "airdate" => "29 Apr 1987", "runtime" => 30, "rating" => 9, "summary" => "Mercenary Tao made short work of Bora, but Goku won't prove to be so easy. Goku is determined to avenge his friend's death and hang on to the Dragon Balls. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436868.jpg"),
        array("id" => "s3e4", "season" => 3, "number" => 4, "name" => "Korin Tower", "airdate" => "6 May 1987", "runtime" => 30, "rating" => 9, "summary" => "Goku attempts to climb the Korin Tower in hopes of finding the Sacred Water. Legend has it that whoever drinks it will be rewarded with amazing new powers.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436867.jpg"),
        array("id" => "s3e5", "season" => 3, "number" => 5, "name" => "Sacred Water", "airdate" => "13 May 1987", "runtime" => 30, "rating" => 8.5, "summary" => "Goku pushes on in an attempt to capture the bottle of Sacred Water from Korin. Meanwhile, Mercenary Tao prepares for a rematch against Goku.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436866.jpg"),
        array("id" => "s3e6", "season" => 3, "number" => 6, "name" => "The Return of Goku", "airdate" => "20 May 1987", "runtime" => 30, "rating" => 9, "summary" => "The fight of the century is about to begin when Goku and Mercenary Tao face off for a rematch. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436865.jpg"),
        array("id" => "s3e7", "season" => 3, "number" => 7, "name" => "The Last of Mercenary Tao", "airdate" => "27 May 1987", "runtime" => 30, "rating" => 9.3, "summary" => "What will Tao find at the top of the tower? And more importantly, what awaits Goku when the angry assassin comes back down?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436864.jpg"),
        array("id" => "s3e8", "season" => 3, "number" => 8, "name" => "Confront the Red Ribbon Army", "airdate" => "10 Jun 1987", "runtime" => 30, "rating" => 8, "summary" => "Goku makes his way to the Red Ribbon Army headquarters to take the Dragon Balls from them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436863.jpg"),
        array("id" => "s3e9", "season" => 3, "number" => 9, "name" => "A Real Bind", "airdate" => "17 Jun 1987", "runtime" => 30, "rating" => 9, "summary" => "Goku's best friends have decided to help him. Can this small group of good guys conquer the legions of evil that await them?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436862.jpg"),
        array("id" => "s3e10", "season" => 3, "number" => 10, "name" => "The End of Commander Red", "airdate" => "24 Jun 1987", "runtime" => 30, "rating" => 9, "summary" => "In an attempt to acquire two Dragon Balls, Goku must face Commander Red and his soldiers. The ultimate battle between good and evil begins! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436861.jpg"),
        array("id" => "s3e11", "season" => 3, "number" => 11, "name" => "The Last Dragon Ball", "airdate" => "1 Jul 1987", "runtime" => 30, "rating" => 9.8, "summary" => "Staff Officer Black is on the attack, and his sights are set on Goku. The showdown between good and evil comes to its thrilling conclusion! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436860.jpg"),
        array("id" => "s3e12", "season" => 3, "number" => 12, "name" => "Who is Fortuneteller Baba?", "airdate" => "8 Jul 1987", "runtime" => 30, "rating" => 8.5, "summary" => "Master Roshi sends Goku and his friends on a quest to find the mysterious Fortuneteller Baba. She possesses the power to find lost things.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/433/1084541.jpg"),
        array("id" => "s3e13", "season" => 3, "number" => 13, "name" => "We Are the Five Warriors", "airdate" => "15 Jul 1987", "runtime" => 30, "rating" => 8.8, "summary" => "Krillin must face-off against a warrior with real bite! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436856.jpg"),
        array("id" => "s3e14", "season" => 3, "number" => 14, "name" => "Deadly Battle", "airdate" => "22 Jul 1987", "runtime" => 30, "rating" => 8.3, "summary" => "How do you fight someone you can't see? That's the problem Yamcha must face as he continues his fight against an invisible man! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436855.jpg"),
        array("id" => "s3e15", "season" => 3, "number" => 15, "name" => "Goku's Turn", "airdate" => "29 Jul 1987", "runtime" => 30, "rating" => 8, "summary" => "Fortuneteller Baba unleashes a threat that will test the heroes' skills and bring them to the brink of destruction: the third fighter! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436854.jpg"),
        array("id" => "s3e16", "season" => 3, "number" => 16, "name" => "The Devilmite Beam", "airdate" => "5 Aug 1987", "runtime" => 30, "rating" => 8.5, "summary" => "Goku has a big problem to solve: How can he defeat a 5,000-year-old mummy that has never been defeated? But this is only the third of Baba's fighters! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436852.jpg"),
        array("id" => "s3e17", "season" => 3, "number" => 17, "name" => "The Mysterious Fifth Man", "airdate" => "12 Aug 1987", "runtime" => 30, "rating" => 8.8, "summary" => "The battle for the last Dragon Ball continues! Now Goku has to face the fourth fighter and his deadly Devilmite Beam.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436851.jpg"),
        array("id" => "s3e18", "season" => 3, "number" => 18, "name" => "The Strong Ones", "airdate" => "19 Aug 1987", "runtime" => 30, "rating" => 10, "summary" => "The final battle in Fortuneteller Baba's tournament has begun, and it is quickly proving to be one for the ages!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436850.jpg"),
        array("id" => "s3e19", "season" => 3, "number" => 19, "name" => "True Colors of the Masked Man", "airdate" => "26 Aug 1987", "runtime" => 30, "rating" => 9.3, "summary" => "The battle between Goku and the masked fighter concludes in an unimaginable showdown that will forever change our hero. Meanwhile, Emperor Pilaf forges a plan to steal Goku's Dragon Balls once again.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436849.jpg"),
        array("id" => "s3e20", "season" => 3, "number" => 20, "name" => "Pilaf's Tactics", "airdate" => "2 Sep 1987", "runtime" => 30, "rating" => 7.3, "summary" => "The seventh Dragon Ball is in the possession of the greedy Emperor Pilaf and secured by his mechanized arsenal! Can Goku take the last ball? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436847.jpg"),
        array("id" => "s3e21", "season" => 3, "number" => 21, "name" => "The Eternal Dragon Rises", "airdate" => "9 Sep 1987", "runtime" => 30, "rating" => 8.5, "summary" => "Goku has collected all seven Dragon Balls! So it's off to the land of Korin to revive Upa's beloved father. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436846.jpg"),
        array("id" => "s3e22", "season" => 3, "number" => 22, "name" => "Terror and Plague", "airdate" => "16 Sep 1987", "runtime" => 30, "rating" => 7.3, "summary" => "Goku gets into trouble when he meets Chao, a little girl who persuades him to save her village from the two dangerous criminals Plague and Terror.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436845.jpg"),
        array("id" => "s3e23", "season" => 3, "number" => 23, "name" => "Goku vs. Sky Dragon", "airdate" => "23 Sep 1987", "runtime" => 30, "rating" => 7.8, "summary" => "Goku gets into the middle of a dispute between two martial arts schools, Chin-Star and Phantom-Fang. When Goku makes enemies with Sky Dragon, the leader of Phantom Fang, he must defend the Chin-Star School in a fight to determine the master of martial arts. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436844.jpg"),
        array("id" => "s3e24", "season" => 3, "number" => 24, "name" => "Goku Goes to Demon Land", "airdate" => "30 Sep 1987", "runtime" => 30, "rating" => 7.3, "summary" => "Goku's journey takes him to a small village terrorized by dozens of demons. The princess of the village was kidnapped by these fearsome creatures, and the king asks Goku for his help. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436842.jpg"),
        array("id" => "s3e25", "season" => 3, "number" => 25, "name" => "The Rampage of InoShikaCho", "airdate" => "7 Oct 1987", "runtime" => 30, "rating" => 7.3, "summary" => "The monster InoShikaCho is coming for Goku! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436841.jpg"),
        array("id" => "s3e26", "season" => 3, "number" => 26, "name" => "Which Way to Papaya Island?", "airdate" => "14 Oct 1987", "runtime" => 30, "rating" => 8, "summary" => "Three years have passed since Master Roshi sent Goku off. But before the tournament begins, he must learn a difficult lesson about deception and betrayal.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436840.jpg"),
        array("id" => "s3e27", "season" => 3, "number" => 27, "name" => "Rivals and Arrivals", "airdate" => "21 Oct 1987", "runtime" => 30, "rating" => 7.5, "summary" => "Master Roshi and the rest of the gang head to the World Martial Arts Tournament but Goku is still missing. If he doesn't reach the sign-in booth on time, he won't get to compete! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436839.jpg"),
        array("id" => "s3e28", "season" => 3, "number" => 28, "name" => "Preliminary Peril", "airdate" => "28 Oct 1987", "runtime" => 30, "rating" => 7.8, "summary" => "The World Martial Arts Tournament begins! Among the competitors is a dangerous opponent who almost destroyed Goku in their first encounter. Get ready for action! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436838.jpg"),
        array("id" => "s3e29", "season" => 3, "number" => 29, "name" => "Then There Were Eight", "airdate" => "4 Nov 1987", "runtime" => 30, "rating" => 7.8, "summary" => "Out of 182 fighters, only 8 will survive the elimination round. As the battles continue, Goku, Krillin and Yamcha fight to stay on top! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436837.jpg"),
        array("id" => "s3e30", "season" => 3, "number" => 30, "name" => "Yamcha vs. Tien", "airdate" => "11 Nov 1987", "runtime" => 30, "rating" => 8, "summary" => "The elimination round is over and Goku, Yamcha and Krillin are among the 8 finalists. The first round: Yamcha fights against his new rival, Tien! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436836.jpg"),
        array("id" => "s3e31", "season" => 3, "number" => 31, "name" => "Yamcha's Big Break", "airdate" => "18 Nov 1987", "runtime" => 30, "rating" => 8, "summary" => "The first fight in the quarterfinals is in full swing, with Yamcha challenging Tien. With these two warriors in battle, one thing is for sure: sparks will fly! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436835.jpg"),
        array("id" => "s3e32", "season" => 3, "number" => 32, "name" => "Full-Moon Vengeance", "airdate" => "25 Nov 1987", "runtime" => 30, "rating" => 8, "summary" => "Man-Wolf and Jackie Chun face each other in the second match of the quarterfinals. For Man-Wolf this fight is not about the martial arts title. It is about revenge! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436834.jpg"),
        array("id" => "s3e33", "season" => 3, "number" => 33, "name" => "The Dodon Wave", "airdate" => "2 Dec 1987", "runtime" => 30, "rating" => 8, "summary" => "In the third fight of the quarterfinals Krillin faces Chiaotzu, who controls the Dodon Wave.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436833.jpg"),
        array("id" => "s3e34", "season" => 3, "number" => 34, "name" => "Counting Controversy!!", "airdate" => "9 Dec 1987", "runtime" => 30, "rating" => 8.5, "summary" => "Krillin has his hands full as he continues his battle against Chiaotzu, who unleashes an even deadlier attack than the Dodon Wave!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436832.jpg"),
        array("id" => "s3e35", "season" => 3, "number" => 35, "name" => "Goku Enters the Ring", "airdate" => "16 Dec 1987", "runtime" => 30, "rating" => 7.8, "summary" => "In the fourth fight of the quarterfinals of the tournament Goku meets Panput, the world-famous fighter and action star. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436831.jpg"),
        array("id" => "s3e36", "season" => 3, "number" => 36, "name" => "Tien Shinhan vs. Jackie Chun", "airdate" => "23 Dec 1987", "runtime" => 30, "rating" => 8.5, "summary" => "The semifinal round begins with an extraordinary fight between the young Tien and the experienced champion Jackie Chun. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436830.jpg"),
        array("id" => "s3e37", "season" => 3, "number" => 37, "name" => "Stepping Down", "airdate" => "30 Dec 1987", "runtime" => 30, "rating" => 8.8, "summary" => "The fight between Jackie Chun and Tien takes on epic proportions as they continue their struggle, using every trick and technique in the book!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436829.jpg"),
        array("id" => "s3e38", "season" => 3, "number" => 38, "name" => "Goku vs. Krillin", "airdate" => "6 Jan 1988", "runtime" => 30, "rating" => 8.3, "summary" => "In the sixth fight of the World Martial Arts Tournament, friends become enemies as Goku and Krillin go head-to-head.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436828.jpg"),
        array("id" => "s3e39", "season" => 3, "number" => 39, "name" => "Tail's Tale", "airdate" => "13 Jan 1988", "runtime" => 30, "rating" => 8.5, "summary" => "The battle between Goku and Krillin comes to a head. What started as a friendly fight turns into an all-out war after Krillin pulls a sneaky stunt behind Goku's back. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436827.jpg"),
        array("id" => "s3e40", "season" => 3, "number" => 40, "name" => "Final Match: Goku vs. Tien Shinhan", "airdate" => "20 Jan 1988", "runtime" => 30, "rating" => 8.3, "summary" => "The final match in the 22nd World Martial Arts Tournament is about to begin! Goku faces Tien in a thrilling battle to see who will become the next Master of Martial Arts! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436826.jpg"),
        array("id" => "s3e41", "season" => 3, "number" => 41, "name" => "Victory's Edge", "airdate" => "27 Jan 1988", "runtime" => 30, "rating" => 9, "summary" => "Bruised and on the brink of destruction, Goku finds himself at the mercy of Tien, as the final match in the World Martial Arts Tournament continues.  Who will win the ultimate battle? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436825.jpg"),
        array("id" => "s3e42", "season" => 3, "number" => 42, "name" => "Tien's Insurrection", "airdate" => "3 Feb 1988", "runtime" => 30, "rating" => 9.3, "summary" => "A dramatic turn of events infuriates Tien and brings him to renewed focus and determination. There is only one outcome that satisfies the proud Tien, as he unveils a sinister new attack!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436823.jpg"),
        array("id" => "s3e43", "season" => 3, "number" => 43, "name" => "The Spirit Cannon", "airdate" => "10 Feb 1988", "runtime" => 30, "rating" => 10, "summary" => "Tien prepares to unleash the destructive power of the Spirit Cannon! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085044.jpg"),
        array("id" => "s3e44", "season" => 3, "number" => 44, "name" => "The Fallen", "airdate" => "17 Feb 1988", "runtime" => 30, "rating" => 10, "summary" => "The Spirit Cannon has left both fighters weary and exhausted. With the stage destroyed, Tien and Goku plummet towards the Earth, with the one who lands first losing the fight! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436822.jpg"),
    )),
    array("number" => 4, "name" => "King Piccolo Saga", "rating" => 8.2, "episodes" => array(
        array("id" => "s4e1", "season" => 4, "number" => 1, "name" => "Enter King Piccolo", "airdate" => "24 Feb 1988", "runtime" => 30, "rating" => 8.8, "summary" => "While Goku sets out on a quest for revenge, his friends try to discover the identity of Krillin's killer. All the clues lead to Master Roshi's past and a demon named King Piccolo! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085699.jpg"),
        array("id" => "s4e2", "season" => 4, "number" => 2, "name" => "Tambourine Attacks!", "airdate" => "2 Mar 1988", "runtime" => 30, "rating" => 8.5, "summary" => "King Piccolo has begun his sinister plan to conquer the world. All he needs are the seven Dragon Balls and the death of all the members of the Martial Arts Society.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085717.jpg"),
        array("id" => "s4e3", "season" => 4, "number" => 3, "name" => "Mark of the Demon", "airdate" => "9 Mar 1988", "runtime" => 30, "rating" => 7.3, "summary" => "King Piccolo has sent Tambourine to kill all the warriors that could foil his plan. Goku meets a mountain man - but is he friend or foe? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085796.jpg"),
        array("id" => "s4e4", "season" => 4, "number" => 4, "name" => "Here Comes Yajirobe", "airdate" => "16 Mar 1988", "runtime" => 30, "rating" => 8, "summary" => "Goku fights for his honor after a mountain boy accuses him of stealing his fish. Meanwhile, Goku's friends desperately search for a way to stop King Piccolo's evil plan. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085813.jpg"),
        array("id" => "s4e5", "season" => 4, "number" => 5, "name" => "Terrible Tambourine", "airdate" => "23 Mar 1988", "runtime" => 30, "rating" => 8, "summary" => "Tambourine continues his campaign to slaughter the martial artists and sets his sight on Yamcha! Master Roshi embarks on a race for the Dragon Balls to stay ahead of the competition, King Piccolo and his dastardly horde. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085823.jpg"),
        array("id" => "s4e6", "season" => 4, "number" => 6, "name" => "Tien's Atonement", "airdate" => "6 Apr 1988", "runtime" => 30, "rating" => 8.3, "summary" => "Tambourine closes in on Goku and Yajirobe. To obtain one of the Dragon Balls, Tien must atone for the brutality of his past. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085843.jpg"),
        array("id" => "s4e7", "season" => 4, "number" => 7, "name" => "Goku's Revenge", "airdate" => "13 Apr 1988", "runtime" => 30, "rating" => 8.3, "summary" => "While Goku fights Tambourine to avenge Krillin's death, Master Roshi, Tien, and Chiaotzu continue their race against King Piccolo for the Dragon Balls. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1085863.jpg"),
        array("id" => "s4e8", "season" => 4, "number" => 8, "name" => "Goku vs. King Piccolo", "airdate" => "20 Apr 1988", "runtime" => 30, "rating" => 8.5, "summary" => "Goku fights for his life as King Piccolo seeks revenge for the deaths of Cymbal and Tambourine.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086160.jpg"),
        array("id" => "s4e9", "season" => 4, "number" => 9, "name" => "Piccolo Closes In", "airdate" => "4 May 1988", "runtime" => 30, "rating" => 7.8, "summary" => "Goku makes a final stand against the seemingly indestructable King Piccolo. As Master Roshi and others continue their pursuit of the Dragon Balls, it becomes clear that the trail leads to the dark forces of King Piccolo. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086307.jpg"),
        array("id" => "s4e10", "season" => 4, "number" => 10, "name" => "Roshi's Gambit", "airdate" => "11 May 1988", "runtime" => 30, "rating" => 8.5, "summary" => "Master Roshi answers the call for a hero by placing himself between King Piccolo and the remaining Dragon Balls. However, in his attempt to save the world, he may have to pay the ultimate price. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086312.jpg"),
        array("id" => "s4e11", "season" => 4, "number" => 11, "name" => "King Piccolo's Wish", "airdate" => "18 May 1988", "runtime" => 30, "rating" => 8.3, "summary" => "Having summoned the Eternal Dragon and with no one to oppose him, King Piccolo prepares to make a wish that, if granted, could become the world's greatest nightmare! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086316.jpg"),
        array("id" => "s4e12", "season" => 4, "number" => 12, "name" => "Siege on Chow Castle", "airdate" => "25 May 1988", "runtime" => 30, "rating" => 7.8, "summary" => "King Piccolo sets out to conquer the world and he begins with the peaceful inhabitants of King Furry's realm. Meanwhile, Goku hopes to regain his strength by visiting Master Korin's Tower.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086320.jpg"),
        array("id" => "s4e13", "season" => 4, "number" => 13, "name" => "Conquest and Power", "airdate" => "1 Jun 1988", "runtime" => 30, "rating" => 7.5, "summary" => "Goku's reunion with Master Korin is tinged with hope and disappointment as the hero learns shocking news! Meanwhile, King Piccolo tries to force King Furry's obedience by displaying a cruel brutality towards his kingdom.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086325.jpg"),
        array("id" => "s4e14", "season" => 4, "number" => 14, "name" => "Awaken Darkness", "airdate" => "8 Jun 1988", "runtime" => 30, "rating" => 6.8, "summary" => "Goku embarks on a dangerous quest to find Ultra Divine Water. One sip could mean incredible power - or a painful death! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086326.jpg"),
        array("id" => "s4e15", "season" => 4, "number" => 15, "name" => "A Taste of Destiny", "airdate" => "22 Jun 1988", "runtime" => 30, "rating" => 8, "summary" => "Goku finally finds Darkness, the keeper of the Ultra Divine Water. After Goku proves himself worthy, Darkness allows him to drink the dangerous potion. But will it make him stronger or will he die? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086328.jpg"),
        array("id" => "s4e16", "season" => 4, "number" => 16, "name" => "The Ultimate Sacrifice", "airdate" => "29 Jun 1988", "runtime" => 30, "rating" => 7.8, "summary" => "Goku and Yajirobe return to Korin's tower, where Goku discovers his new powers and receives another Nimbus cloud. Meanwhile, Tien has mastered the Evil Containment Wave and decides to use it against King Piccolo.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086329.jpg"),
        array("id" => "s4e17", "season" => 4, "number" => 17, "name" => "Prelude to Vengeance", "airdate" => "6 Jul 1988", "runtime" => 30, "rating" => 8.3, "summary" => "King Piccolo has declared the destruction of the world, one sector at a time. First up is the Western City, home to Bulma's parents. Tien prepares to fight King Piccolo, but a new threat looms over everyone. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086338.jpg"),
        array("id" => "s4e18", "season" => 4, "number" => 18, "name" => "Battle Cry", "airdate" => "20 Jul 1988", "runtime" => 30, "rating" => 8.5, "summary" => "Tien must go through Drum before he can fight King Piccolo. The problem is that Drum moves faster than all three of Tien's eyes! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436820.jpg"),
