        array("id" => "s4e20", "season" => 4, "number" => 20, "name" => "The Biggest Crisis", "airdate" => "3 Aug 1988", "runtime" => 30, "rating" => 9.3, "summary" => "Goku is not ready to give up power to King Piccolo without a fight. It's a fierce battle, but even Goku has his limits. How much can he take? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086357.jpg"),
        array("id" => "s4e21", "season" => 4, "number" => 21, "name" => "Final Showdown", "airdate" => "10 Aug 1988", "runtime" => 30, "rating" => 9.5, "summary" => "King Piccolo gains the advantage as he dissects Goku limb by limb. Will he surrender to King Piccolo or decide to fight and risk his own life? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/434/1086361.jpg"),
