    array("number" => 5, "name" => "Piccolo Jr. Saga", "rating" => 8.3, "episodes" => array(
        array("id" => "s5e1", "season" => 5, "number" => 1, "name" => "Lost and Found", "airdate" => "17 Aug 1988", "runtime" => 30, "rating" => 7.8, "summary" => "The Secret of the Nyoi-BōGoku learns that there may be a way to revive his lost friends - a face-to-face meeting with the creator of the Dragon Balls! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436817.jpg"),
