        array("id" => "s5e6", "season" => 5, "number" => 6, "name" => "Secret of the Woods", "airdate" => "28 Sep 1988", "runtime" => 30, "rating" => 7, "summary" => "In search of a worthy sparring partner, Goku stumbles upon a surprising discovery hidden deep within the secluded labyrinth.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436811.jpg"),
        array("id" => "s5e7", "season" => 5, "number" => 7, "name" => "The Time Room", "airdate" => "12 Oct 1988", "runtime" => 30, "rating" => 8, "summary" => "Goku travels through time where he meets a young Master Roshi and Master Shen! While the two rivals fight for the affections of the same girl, Goku tries to gain a new power with the help of Master Mutaito. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436810.jpg"),
