        array("id" => "s5e10", "season" => 5, "number" => 10, "name" => "Hotter Than Lava", "airdate" => "2 Nov 1988", "runtime" => 30, "rating" => 7, "summary" => "Tien, Yamcha, Chiaotzu and Krillin find themselves in a very hot situation! It's time to put their new training to the test! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436807.jpg"),
