        array("id" => "s5e12", "season" => 5, "number" => 12, "name" => "Preliminary Peril", "airdate" => "16 Nov 1988", "runtime" => 30, "rating" => 8.3, "summary" => "Goku and the others compete in the exciting preliminary round. But the competition threatens to turn ugly when Goku gets a visit from an old adversary. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1436804.jpg"),
